export default function(api) {
  let visible = false, busy = false;
  async function refresh() {
    if (!visible || busy) return;
    busy = true;
    try {
      const settings = await api.getSettings();
      const docs = await api.listDocuments();
      const list = document.getElementById('documents');
      if (!list) return;
      document.getElementById('summary').textContent = docs.length + ' documentos no workspace';
      list.replaceChildren();
      for (const doc of docs.slice(0, settings.limit)) {
        const button = document.createElement('button');
        button.textContent = doc.title + (settings.tags && doc.tags.length ? ' · #' + doc.tags.join(' #') : '');
        button.onclick = async () => { await api.openDocument(doc.id); await api.storage.set({ lastDocument: doc.id }); };
        list.append(button);
      }
    } finally { busy = false; }
  }
  api.registerCommand('inspect', async () => {
    await api.showPanel({title:'Explorador do workspace',width:430,
      html:'<main><small>EXTENSÃO / ÂMAGO</small><h1>Seu workspace</h1><p id="summary">Carregando…</p><button id="refresh">Atualizar documentos</button><section id="documents"></section></main>',
      css:'body{margin:0;background:var(--bg,#101724);color:var(--text,#c8d5e8);font:14px/1.7 system-ui}main{padding:24px}small{color:var(--accent,#78e2df);letter-spacing:2px;font-size:10px}h1{font-size:24px;color:var(--strong,#fff)}button{display:block;width:100%;text-align:left;padding:12px;margin:9px 0;background:var(--panel,#172234);color:inherit;border:1px solid var(--border,#345);border-radius:7px;cursor:pointer}button:hover{border-color:var(--accent,#78e2df)}#summary{font-size:12px;opacity:.7}'
    });
    visible=true;document.getElementById('refresh').onclick=refresh;await refresh();
  });
  api.on('workspace:change', refresh);api.on('settings:change', refresh);api.on('view:close',()=>visible=false);
}
